/* Manage redesign: one Knowledge Studio, setup guide, Sources with accounts */
"Bring documents into {0}, classify them and publish them to the right people.": "Đưa tài liệu vào {0}, phân loại và xuất bản cho đúng người.",
"Review and publish documents for the collections you look after.": "Kiểm duyệt và xuất bản tài liệu cho các bộ sưu tập bạn phụ trách.",
