"Create collections": "Tạo bộ sưu tập",
"Where documents live and who can read them. Make one per access boundary — a team, a function, the whole company.": "Tài liệu nằm ở đâu và ai được đọc. Mỗi ranh giới truy cập một bộ sưu tập — một nhóm, một bộ phận, hay toàn công ty.",
"Load master data": "Nạp dữ liệu chủ",
"The topics documents are filed under, with the keywords that recognise them. Import them before the first sync, so every document is classified as it arrives.": "Các chủ đề để xếp tài liệu, kèm từ khóa nhận diện. Hãy nhập trước lần đồng bộ đầu tiên để mọi tài liệu được phân loại ngay khi vào.",
