"Folders for related conversations and the documents they start from.": "Thư mục cho các cuộc trò chuyện liên quan và tài liệu mà chúng bắt đầu từ đó.",
"A project keeps related chats together, with the documents every new chat in it starts from. Only you can see your projects.": "Dự án gom các cuộc trò chuyện liên quan lại với nhau, cùng các tài liệu mà mọi cuộc trò chuyện mới trong đó bắt đầu từ đó. Chỉ bạn thấy được dự án của mình.",
