"Nothing here yet": "Chưa có gì ở đây",
"Documents you open, your conversations and your work show up here, newest first.": "Tài liệu bạn mở, các cuộc trò chuyện và công việc của bạn sẽ hiện ở đây, mới nhất trước.",
"Start a chat": "Bắt đầu trò chuyện",
"Search recent": "Tìm trong mục gần đây",
"items": "mục",
"Deleted “{0}”. Its {1} stay in AI Chat.": "Đã xóa “{0}”. {1} của dự án vẫn ở trong Trò chuyện AI.",
