"Go to AI Chat": "Đến Trò chuyện AI",
"AI Chat: start a conversation or pick up an earlier one. Attach files or choose exactly what to search.": "Trò chuyện AI: bắt đầu một cuộc trò chuyện hoặc tiếp tục cuộc trò chuyện trước. Đính kèm tệp hoặc chọn chính xác phạm vi tìm kiếm.",
"Ask a question above. Your conversations stay here, so you can pick one up later.": "Đặt câu hỏi ở trên. Các cuộc trò chuyện của bạn được lưu tại đây để bạn tiếp tục sau.",
"What you shared with your team, where it stands and what to do next.": "Những gì bạn đã chia sẻ với nhóm, tình trạng hiện tại và việc cần làm tiếp theo.",
"Share a document with your team. You check what the assistant suggests, then a reviewer publishes it.": "Chia sẻ tài liệu với nhóm. Bạn kiểm tra đề xuất của trợ lý, sau đó người kiểm duyệt sẽ xuất bản.",
"Documents you share with your team show up here, with where they stand.": "Tài liệu bạn chia sẻ với nhóm sẽ hiện ở đây, kèm tình trạng hiện tại.",
"You check the details before anything is sent.": "Bạn kiểm tra thông tin trước khi gửi đi.",
"The assistant suggests a title, topics and a collection. You check them next.": "Trợ lý đề xuất tiêu đề, chủ đề và bộ sưu tập. Bạn sẽ kiểm tra ở bước tiếp theo.",
