"Check the details": "Kiểm tra thông tin",
"The assistant suggested these from your file. Change anything that’s off — reviewers see what you confirmed.": "Trợ lý đề xuất các thông tin này từ tệp của bạn. Hãy sửa những gì chưa đúng — người kiểm duyệt sẽ thấy những gì bạn đã xác nhận.",
"Details for {0}": "Thông tin cho {0}",
"Remove personal details before you submit, or say in the note why they’re needed.": "Hãy xóa thông tin cá nhân trước khi gửi, hoặc ghi chú lý do cần giữ lại.",
"Looks like “{0}” ({1}% similar title). If it replaces that document, submit a new version of it instead.": "Giống “{0}” (tiêu đề tương tự {1}%). Nếu tài liệu này thay thế tài liệu đó, hãy gửi phiên bản mới của tài liệu đó.",
"No clear topic. Add one if you know it.": "Chưa rõ chủ đề. Hãy thêm nếu bạn biết.",
