"A first sync published these with the topics the assistant applied, or without one. Confirm in bulk.": "Lần đồng bộ đầu đã xuất bản các tài liệu này với chủ đề do trợ lý gắn, hoặc chưa có chủ đề. Xác nhận hàng loạt.",
"Without a topic": "Chưa có chủ đề",
"Documents without an owner or a summary are harder to trust. Fill in what’s missing.": "Tài liệu thiếu người phụ trách hoặc tóm tắt khó được tin cậy. Hãy điền phần còn thiếu.",
"Documents you look after all have an owner and a summary.": "Mọi tài liệu bạn phụ trách đều có người phụ trách và tóm tắt.",
"A workspace admin decides": "Quản trị viên workspace quyết định",
"Show the classification prompt": "Xem prompt phân loại",
"Export topics": "Xuất danh sách chủ đề",
"The pipeline matches them by name only. Show just these.": "Quy trình xử lý chỉ khớp theo tên. Chỉ hiện các chủ đề này.",
"When reviewers move documents to another topic, the words their titles share are keyword candidates. Nothing changes until you add one.": "Khi người kiểm duyệt chuyển tài liệu sang chủ đề khác, các từ chung trong tiêu đề sẽ thành từ khóa đề xuất. Không có gì thay đổi cho đến khi bạn thêm.",
"Reviewers moved {0} to {1}": "Người kiểm duyệt đã chuyển {0} sang {1}",
"The pipeline had filed it under {0}.": "Quy trình xử lý đã xếp nó vào {0}.",
"The pipeline had filed them under {0}.": "Quy trình xử lý đã xếp chúng vào {0}.",
"The pipeline had found no topic for it.": "Quy trình xử lý không tìm được chủ đề cho nó.",
"The pipeline had found no topic for them.": "Quy trình xử lý không tìm được chủ đề cho chúng.",
"Add as a keyword": "Thêm làm từ khóa",
"In {0} of these titles": "Có trong {0} tiêu đề này",
"One correction isn’t a pattern yet. Add the document as an example, or wait for more.": "Một lần sửa chưa thành quy luật. Hãy thêm tài liệu làm ví dụ, hoặc chờ thêm.",
"Their titles share no new word. Add them as examples instead.": "Tiêu đề của chúng không có từ chung mới. Hãy thêm chúng làm ví dụ.",
"Misled by “{0}”, a keyword of {1}.": "Bị nhầm bởi “{0}”, một từ khóa của {1}.",
"Open topic": "Mở chủ đề",
"Add as examples": "Thêm làm ví dụ",
"{0} · re-checking {1}…": "{0} · đang kiểm tra lại {1}…",
"{0} · {1} re-checked, {2} changed topic. No re-indexing needed.": "{0} · đã kiểm tra lại {1}, {2} đổi chủ đề. Không cần lập chỉ mục lại.",
"{0} · {1} re-checked, none changed topic. No re-indexing needed.": "{0} · đã kiểm tra lại {1}, không tài liệu nào đổi chủ đề. Không cần lập chỉ mục lại.",
"Dismissed {0}": "Đã bỏ qua {0}",
